    bg=cnt.most_common(1)[0][0]
    fgv=[v for v in cnt if v not in (bg,) and cnt[v]>0]
    # two bands: contiguous runs of rows containing fg
    bandrows=[r for r in range(H_) if any(din[r][c] in fgv or (fgv==[0] and din[r][c]==0) for c in range(W_))]
    fgv=fgv if fgv else [0]
