            ov=len(m&Aset)-0
            score=(ov, -len(mi-Aset))
            if best is None or score>best[0]: best=(score,dr,dc,A,Bd,Aset,Bset,midr)
    (score,dr,dc,A,Bd,Aset,Bset,midr)=best
    m={(r+dr,c+dc) for (r,c) in Aset}
    # choose direction: which band is incomplete? compare symmetric: also try B->A
    best2=None
    for dr2 in range(-(Bd[0]-A[-1])-1, H_):
        for dc2 in range(-W_,W_+1):
            m2={(r+dr2,c+dc2) for (r,c) in Bset}
            midr2=set(range(min(Bd),max(Bd)+1))
            mi2={(r,c) for (r,c) in m2 if r in midr2 and 0<=c<W_}
            ov2=len(m2&Bset)
            sc2=(ov2,-len(mi2-Bset))
            if best2 is None or sc2>best2[0]: best2=(sc2,dr2,dc2,midr2,m2)
    (sc2,dr2,dc2,midr2,m2)=best2
    missA=sorted({(r,c) for (r,c) in m if r in midr and 0<=c<W_}-Aset)
    missB=sorted({(r,c) for (r,c) in m2 if r in midr2 and 0<=c<W_}-Bset)
    ovA=score[0]; ovB=sc2[0]
