def bands_bg(g):
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    rows=[r for r,row in enumerate(g) if any(v!=bg for v in row)]
    # split into contiguous groups
    groups=[];cur=[rows[0]]
    for r in rows[1:]:
